                  dict(label='Tipo de fuente', points=[
                    dict(text='Es una cita de una obra secundaria que transcribe lemas del día del Corpus de Sangre sin precisar su fuente primaria; hay que tratarla como un testimonio mediado y traducido.', quotes=[Q('en_reapers','with an uprising known as \'Bloody Corpus\''), Q('es_segadores','El 7 de junio, día del Corpus Christi'.replace('El 7 de junio, día del Corpus Christi','La sublevación comienza con el Corpus de Sangre del 7 de junio de 1640'))])]),
